import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { meta, run } from './app.mjs';

// All expected outputs in cases.json are manually derived, never generated by run().
const cases = JSON.parse(readFileSync(new URL('./cases.json', import.meta.url), 'utf8'));
assert.ok(Array.isArray(cases) && cases.length >= 4);
assert.ok(cases.filter(c => Object.hasOwn(c, 'expected')).length >= 2);
assert.ok(cases.some(c => c.error === true));
assert.match(meta.id, /^p(?:3[1-9]|40)$/);
assert.equal(meta.version, '1.1.0');
for (const key of ['title', 'description', 'category']) assert.ok(typeof meta[key] === 'string' && meta[key].length > 0);
assert.ok(meta.example && typeof meta.example === 'object' && !Array.isArray(meta.example));
let passed = 0;
for (const fixture of cases) {
  const original = structuredClone(fixture.input);
  if (fixture.error) {
    assert.throws(() => run(fixture.input), error => error instanceof Error && error.message.length > 0 && (!fixture.errorMessage || error.message.includes(fixture.errorMessage)), fixture.name);
  } else {
    const actual = run(fixture.input);
    assert.deepStrictEqual(actual, fixture.expected, fixture.name);
    assert.deepStrictEqual(JSON.parse(JSON.stringify(actual)), actual, `${fixture.name}: serializable result`);
    assert.deepStrictEqual(run(fixture.input), actual, `${fixture.name}: deterministic result`);
  }
  assert.deepStrictEqual(fixture.input, original, `${fixture.name}: input not mutated`);
  passed++;
}
for (const invalid of [null, undefined, [], 1, 'bad input']) assert.throws(() => run(invalid), Error);
const exampleBefore = structuredClone(meta.example);
const exampleResult = run(meta.example);
assert.ok(exampleResult && typeof exampleResult === 'object' && typeof exampleResult.then !== 'function');
assert.deepStrictEqual(JSON.parse(JSON.stringify(exampleResult)), exampleResult);
assert.deepStrictEqual(meta.example, exampleBefore);
console.log(`${meta.id}: ${passed}/${cases.length} fixtures passed; root validation and example smoke passed`);
